import {BROW_TEMPLATES,previewPath} from './brow-templates.js';
import {PALETTE} from './cosmetics.js';
export function mountCosmetics(root,{getState,before,change,action}){
 root.innerHTML=`<h3>Màu môi & dáng mày</h3><p class="muted">Mô phỏng thiết kế trên ảnh. Màu sau lành phụ thuộc cơ địa và kỹ thuật; chế độ thay dáng giảm ảnh hưởng mày cũ ở mức vừa phải để minh họa.</p><fieldset disabled><details open><summary>Phun / xăm môi</summary><label><input type="checkbox" data-path="lips.enabled"> Bật màu môi</label><div class="swatches">${PALETTE.map(([name,color])=>`<button type="button" data-color="${color}" title="${name}" aria-label="${name}" style="--swatch:${color}"></button>`).join('')}</div><label>Màu tùy chọn <input type="color" data-path="lips.color"></label>${range('lips.opacity','Độ đậm',0,100)}${range('lips.upper','Phủ môi trên',0,100)}${range('lips.lower','Phủ môi dưới',0,100)}${range('lips.feather','Mềm viền',0,100)}<button data-action="resetLips">Đặt lại môi</button></details><details><summary>Phun / xăm mày</summary><label><input type="checkbox" data-path="brows.enabled"> Bật thiết kế mày</label><div class="brow-template-grid">${BROW_TEMPLATES.map(p=>`<button type="button" data-brow-template="${p.id}" aria-label="Chọn mẫu ${p.name}"><svg viewBox="0 0 160 52" aria-hidden="true"><path d="${previewPath(p.id)}"/></svg><span>${p.name}</span></button>`).join('')}</div><label>Độ rõ <select data-path="brows.clarity"><option value="defined">Rõ dáng</option><option value="natural">Tự nhiên</option></select></label><label><input type="checkbox" data-path="brows.guide"> Hiện đường định hình khi chỉnh</label><label>Cách xem <select data-path="brows.mode"><option value="overlay">Phủ mẫu trên mày thật</option><option value="replace">Làm mờ mày gốc & thay dáng</option></select></label>${range('brows.fade','Mức làm mờ mày gốc',0,100)}<p class="muted">Thay dáng ước lượng màu da lân cận, chỉ làm mờ có giới hạn để tránh bệt. Mày gốc vẫn có thể nhìn thấy. Không phản ánh khả năng xóa xăm hoặc kết quả sau làm.</p><label>Hiệu ứng <select data-path="brows.style"><option value="powder">Tán bột</option><option value="strokes">Nét sợi minh họa</option><option value="ombre">Ombre</option><option value="hybrid">Đầu sợi / Đuôi bột</option></select></label><label>Màu <input type="color" data-path="brows.color"></label>${range('brows.opacity','Độ đậm',0,100)}<label><input type="checkbox" data-path="brows.linked"> Chỉnh đồng thời hai bên</label><label><input type="checkbox" data-path="brows.outline"> Chỉ xem viền thiết kế</label>${['left','right'].map(side=>`<details><summary>Mày ${side==='left'?'trái':'phải'} của khách</summary>${range('brows.'+side+'.thickness','Độ dày',50,180)}${range('brows.'+side+'.length','Chiều dài',70,130)}${range('brows.'+side+'.arch','Độ nâng đỉnh',-20,30)}${range('brows.'+side+'.x','Dịch ngang',-20,20)}${range('brows.'+side+'.y','Dịch dọc',-20,20)}${range('brows.'+side+'.rotation','Xoay (độ)',-15,15)}</details>`).join('')}<button data-action="resetBrows">Đặt lại mày</button></details><div class="proposal-actions"><button data-action="saveA">Lưu A</button><button data-action="loadA">Xem A</button><button data-action="saveB">Lưu B</button><button data-action="loadB">Xem B</button></div><p id="proposalStatus" role="status">Chưa lưu phương án.</p></fieldset>`;
 const inputs=[...root.querySelectorAll('[data-path]')];
 function sync(){const state=getState();root.querySelector('[data-path="brows.fade"]').closest('label').hidden=state.brows.mode!=='replace';for(const el of inputs){const v=el.dataset.path.split('.').reduce((v,k)=>v[k],state);if(el.type==='checkbox')el.checked=v;else el.value=v;const out=el.parentElement.querySelector('output');if(out)out.textContent=v;}for(const b of root.querySelectorAll('[data-brow-template]'))b.setAttribute('aria-pressed',String(b.dataset.browTemplate===state.brows.preset));for(const b of root.querySelectorAll('[data-color]'))b.setAttribute('aria-pressed',String(b.dataset.color===state.lips.color));}
 for(const el of inputs){if(el.type==='range')el.addEventListener('pointerdown',before);el.addEventListener('keydown',e=>{if(el.type==='range'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(e.key))before()});el.addEventListener(el.type==='range'||el.type==='color'?'input':'change',()=>{if(el.type!=='range')before();const path=el.dataset.path.split('.'),state=getState(),obj=path.slice(0,-1).reduce((v,k)=>v[k],state),key=path.at(-1);obj[key]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;if(path.length===3&&state.brows.linked){const other=path[1]==='left'?'right':'left';state.brows[other][key]=obj[key]*(key==='x'||key==='rotation'?-1:1);}change();sync()});}
 for(const b of root.querySelectorAll('[data-color]'))b.onclick=()=>{before();getState().lips.color=b.dataset.color;getState().lips.enabled=true;change();sync()};
 for(const b of root.querySelectorAll('[data-brow-template]'))b.onclick=()=>{before();getState().brows.preset=b.dataset.browTemplate;getState().brows.enabled=true;change();sync()};
 for(const b of root.querySelectorAll('[data-action]'))b.onclick=()=>{action(b.dataset.action);sync()};
 sync();return {sync,setEnabled(v){root.querySelector('fieldset').disabled=!v;},clear(){root.querySelector('#proposalStatus').textContent='Chưa lưu phương án.';sync();}};
}
function range(path,label,min,max){return `<label class="range-label">${label}<output></output><input aria-label="${label}" data-path="${path}" type="range" min="${min}" max="${max}"></label>`}
